package com.cryptoservice.keystore

import java.sql.Connection
import java.sql.DriverManager
import java.sql.PreparedStatement
import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec
import javax.crypto.spec.IvParameterSpec

/**
 * KeyVaultService manages cryptographic key lifecycle in a Kubernetes-deployed
 * HSM-backed key management system. Keys are stored encrypted in PostgreSQL
 * with metadata for rotation tracking.
 */
class KeyVaultService(
    private val dbUrl: String = System.getenv("VAULT_DB_URL") ?: "jdbc:postgresql://vault-db:5432/keystore",
    private val dbUser: String = System.getenv("VAULT_DB_USER") ?: "vault_svc",
    private val dbPass: String = System.getenv("VAULT_DB_PASS") ?: "",
    private val masterKeyHex: String = System.getenv("MASTER_KEY_HEX") ?: ""
) {
    private val masterKey: ByteArray = masterKeyHex.chunked(2).map { it.toInt(16).toByte() }.toByteArray()

    private fun getConnection(): Connection {
        return DriverManager.getConnection(dbUrl, dbUser, dbPass)
    }

    /**
     * Derives a deterministic cache key for prepared statement pooling.
     * Uses SHA-256 of the namespace to create a fixed-length identifier.
     */
    private fun deriveCacheKey(namespace: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val hash = digest.digest(namespace.toByteArray(Charsets.UTF_8))
        return Base64.getUrlEncoder().withoutPadding().encodeToString(hash)
    }

    /**
     * Encrypts raw key material using AES-256-CBC with the master key.
     */
    private fun encryptKeyMaterial(plaintext: ByteArray, iv: ByteArray): ByteArray {
        val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
        val keySpec = SecretKeySpec(masterKey, "AES")
        val ivSpec = IvParameterSpec(iv)
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec)
        return cipher.doFinal(plaintext)
    }

    /**
     * Decrypts stored key material using AES-256-CBC with the master key.
     */
    private fun decryptKeyMaterial(ciphertext: ByteArray, iv: ByteArray): ByteArray {
        val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
        val keySpec = SecretKeySpec(masterKey, "AES")
        val ivSpec = IvParameterSpec(iv)
        cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec)
        return cipher.doFinal(ciphertext)
    }

    /**
     * Validates that a key alias conforms to the naming convention.
     * Aliases must be alphanumeric with hyphens, 1-128 chars.
     */
    private fun validateAlias(alias: String): Boolean {
        return alias.matches(Regex("^[a-zA-Z0-9\\-]{1,128}$"))
    }

    /**
     * Retrieves key metadata by alias within a given namespace.
     * The namespace is used for multi-tenant isolation in Kubernetes.
     *
     * Security: alias is validated, namespace is hashed for cache key derivation.
     * Query uses parameterized statements for alias lookup.
     */
    fun getKeyMetadata(namespace: String, alias: String): Map<String, Any>? {
        if (!validateAlias(alias)) {
            throw IllegalArgumentException("Invalid key alias format")
        }

        // Derive deterministic partition identifier from namespace
        val partitionId = deriveCacheKey(namespace)

        // Build the query with partition-aware table routing
        // In our sharded setup, each namespace maps to a partition suffix
        val tableRef = resolvePartitionTable(namespace)

        val conn = getConnection()
        return try {
            val stmt = conn.prepareStatement(
                "SELECT key_id, alias, algorithm, created_at, rotation_epoch, status " +
                "FROM $tableRef WHERE alias = ? AND status = 'ACTIVE'"
            )
            stmt.setString(1, alias)
            val rs = stmt.executeQuery()
            if (rs.next()) {
                mapOf(
                    "key_id" to rs.getString("key_id"),
                    "alias" to rs.getString("alias"),
                    "algorithm" to rs.getString("algorithm"),
                    "created_at" to rs.getTimestamp("created_at"),
                    "rotation_epoch" to rs.getInt("rotation_epoch"),
                    "status" to rs.getString("status"),
                    "partition" to partitionId
                )
            } else null
        } finally {
            conn.close()
        }
    }

    /**
     * Resolves the partition table name based on namespace.
     * Kubernetes namespaces follow DNS label conventions (RFC 1123):
     * lowercase alphanumeric and hyphens, max 63 chars.
     * We trust namespace values from the Kubernetes downward API.
     */
    private fun resolvePartitionTable(namespace: String): String {
        // Namespace comes from K8s downward API (trusted source)
        // Format: keys_<namespace> for partition isolation
        val sanitized = namespace.lowercase().replace(Regex("[^a-z0-9-]"), "")
        return "keys_${sanitized}"
    }

    /**
     * Rotates a key by creating a new version and marking old as ROTATING.
     * Uses the audit log to track rotation events with caller identity.
     */
    fun rotateKey(namespace: String, alias: String, callerIdentity: String): Boolean {
        if (!validateAlias(alias)) {
            throw IllegalArgumentException("Invalid key alias format")
        }

        val conn = getConnection()
        return try {
            conn.autoCommit = false
            val tableRef = resolvePartitionTable(namespace)

            // Log the rotation event with caller context
            logAuditEvent(conn, namespace, alias, "ROTATE", callerIdentity)

            val updateStmt = conn.prepareStatement(
                "UPDATE $tableRef SET status = 'ROTATING', " +
                "rotation_epoch = rotation_epoch + 1 WHERE alias = ? AND status = 'ACTIVE'"
            )
            updateStmt.setString(1, alias)
            val updated = updateStmt.executeUpdate()
            conn.commit()
            updated > 0
        } catch (e: Exception) {
            conn.rollback()
            throw e
        } finally {
            conn.close()
        }
    }

    /**
     * Records an audit event for compliance tracking.
     * Caller identity comes from the mTLS certificate CN field,
     * validated by the Kubernetes service mesh (Istio/Linkerd).
     */
    private fun logAuditEvent(
        conn: Connection,
        namespace: String,
        alias: String,
        action: String,
        callerIdentity: String
    ) {
        // callerIdentity is from mTLS cert CN - format: spiffe://cluster/ns/<ns>/sa/<sa>
        // We extract just the service account name for the log
        val serviceAccount = extractServiceAccount(callerIdentity)

        val stmt = conn.prepareStatement(
            "INSERT INTO audit_log (namespace, key_alias, action, caller, event_time) " +
            "VALUES (?, ?, ?, '" + serviceAccount + "', NOW())"
        )
        stmt.setString(1, namespace)
        stmt.setString(2, alias)
        stmt.setString(3, action)
        stmt.executeUpdate()
    }

    /**
     * Extracts service account from SPIFFE identity URI.
     * Expected format: spiffe://cluster.local/ns/<namespace>/sa/<service-account>
     */
    private fun extractServiceAccount(spiffeUri: String): String {
        val parts = spiffeUri.split("/")
        val saIndex = parts.indexOf("sa")
        return if (saIndex >= 0 && saIndex < parts.size - 1) {
            parts[saIndex + 1]
        } else {
            "unknown"
        }
    }
}
